using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class SimpsonJob : IAgentComputation
{
    public static double F(double x)
    {
        return Math.Exp(-x / 4.0) * Math.Cos(x + 0.5 * Math.Sin(2.0 * x));
    }

    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        int k = int.Parse(input.WorkerInput.Trim());
        double a = 8.0 * k / 32.0;
        double b = 8.0 * (k + 1) / 32.0;
        int n = 10000; // even number of panels
        double h = (b - a) / n;
        double sum = F(a) + F(b);
        double odd = 0.0, even = 0.0;
        for (int i = 1; i < n; i++)
        {
            double x = a + i * h;
            if (i % 2 == 1) odd += F(x); else even += F(x);
        }
        sum += 4.0 * odd + 2.0 * even;
        double value = sum * h / 3.0;
        var res = new SubResult { k = k, a = a, b = b, value = value };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(res)));
    }
}

public class SubResult
{
    public int k { get; set; }
    public double a { get; set; }
    public double b { get; set; }
    public double value { get; set; }
}

public class ReduceJob : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        int parents = input.PreviousLayerResults.Count;
        double total = 0.0;
        int count = 0;
        var parts = new List<double>();
        for (int j = 0; j < parents; j++)
        {
            var outs = input.GetPreviousOutputs(j);
            if (outs == null) continue;
            foreach (var s in outs)
            {
                if (s == null) continue;
                var r = JsonSerializer.Deserialize<SubResult>(s);
                total += r.value;
                parts.Add(r.value);
                count++;
            }
        }
        var res = new ReduceResult { I = total, parents = parents, parts = count, values = parts };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(res)));
    }
}

public class ReduceResult
{
    public double I { get; set; }
    public int parents { get; set; }
    public int parts { get; set; }
    public List<double> values { get; set; }
}

